def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    bg = most_frequent(grid)

    result = [[bg for _ in range(cols)] for _ in range(rows)]

    for i in range(rows):
        for j in range(cols // 2):
            val = grid[i][j]
            if val != bg:
                result[i][j] = val
                mirror_j = cols - 1 - j
                if result[i][mirror_j] == bg:
                    result[i][mirror_j] = val
                elif result[i][mirror_j] != bg:
                    result[i][j] = result[i][mirror_j]

    return result

def most_frequent(grid):
    counts = {}
    for row in grid:
        for cell in row:
            counts[cell] = counts.get(cell, 0) + 1
    return max(counts, key=counts.get)
